INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1657848, 221537, 35804, '<td valign="top">LOVE the texture and lighting on that pavement! The "warm" mingled with the "cool" color palette..simply luminous...I think the only thing I may have addressed differently would be the little "sun streak" at the upper right of the image running parallel to the top...I may have cloned that puppy out...overall a very intriguing image.</td>', 'LOVE the texture and lighting on that pavement! The "warm" mingled with the "cool" color palette..simply luminous...I think the only thing I may have addressed differently would be the little "sun streak" at the upper right of the image running parallel to the top...I may have cloned that puppy out...overall a very intriguing image.', '2005-08-30 13:34:13.000000', NULL, 1),
(1657852, 223982, 35804, '<td valign="top">...really gorgeous blues...a very dynamic abstract.</td>', '...really gorgeous blues...a very dynamic abstract.', '2005-08-30 13:35:39.000000', NULL, 1),
(1657855, 223948, 35720, '<td valign="top">Well composed shot with beautiful colours,- simple and effective. Great work!</td>', 'Well composed shot with beautiful colours,- simple and effective. Great work!', '2005-08-30 13:36:45.000000', NULL, 1),
(1657863, 223711, 36371, '<td valign="top">Whoa! Is this staged or real? Beautiful shot!</td>', 'Whoa! Is this staged or real? Beautiful shot!', '2005-08-30 13:38:36.000000', NULL, 1),
(1657869, 223868, 41554, '<td valign="top">I think a little bit more DOF would benefit this.</td>', 'I think a little bit more DOF would benefit this.', '2005-08-30 13:40:35.000000', NULL, 1),
(1657871, 223656, 41554, '<td valign="top">If only the glass was clean (or looked like it)...</td>', 'If only the glass was clean (or looked like it)...', '2005-08-30 13:42:28.000000', NULL, 1),
(1657874, 224023, 41554, '<td valign="top">IMHO this would be a great pic if bottom and right were cropped out about 1/5 each.</td>', 'IMHO this would be a great pic if bottom and right were cropped out about 1/5 each.', '2005-08-30 13:45:13.000000', NULL, 1),
(1657876, 223711, 35804, '<td valign="top">A touching image beyond words...this has hit me right in the heart...I am overwhelmed with emotion...a perfect candid,  but so much more really...you have captured something here...so painful yet endearing at the same time. You have captured that "bond".<br/> <br/>This is one of those images that will haunt me for quite some time...thank you for sharing this with us.<br/> <br/>This is my top pick...hands down.</td>', 'A touching image beyond words...this has hit me right in the heart...I am overwhelmed with emotion...a perfect candid,  but so much more really...you have captured something here...so painful yet endearing at the same time. You have captured that "bond". This is one of those images that will haunt me for quite some time...thank you for sharing this with us. This is my top pick...hands down.', '2005-08-30 13:45:41.000000', NULL, 1),
(1657879, 222739, 41554, '<td valign="top">Nice shot, but I find the roof tiles to the right to be distracting. Cropping them out might benefit the pic IMHO.</td>', 'Nice shot, but I find the roof tiles to the right to be distracting. Cropping them out might benefit the pic IMHO.', '2005-08-30 13:47:34.000000', NULL, 1),
(1657886, 223982, 36616, '<td valign="top">Nice study, good cloud reflections</td>', 'Nice study, good cloud reflections', '2005-08-30 13:52:00.000000', NULL, 1),
