(1663437, 224039, 20462, '<td valign="top">nice try, but the subject matter should be of a little bit more interest. or at least better conceived.</td>', 'nice try, but the subject matter should be of a little bit more interest. or at least better conceived.', '2005-08-31 20:27:29.000000', NULL, 1),
(1663440, 224061, 20462, '<td valign="top">forced cropping distracts from this simple shot.</td>', 'forced cropping distracts from this simple shot.', '2005-08-31 20:27:52.000000', NULL, 1),
(1663443, 223952, 20462, '<td valign="top">the abstract always gets punished.  and there are too many distracting elements here to work, so I can''t help you out.</td>', 'the abstract always gets punished.  and there are too many distracting elements here to work, so I can''t help you out.', '2005-08-31 20:28:33.000000', NULL, 1),
(1663444, 222635, 20462, '<td valign="top">seems slightly out of focus or not sharp enough.  good try and original idea here.</td>', 'seems slightly out of focus or not sharp enough.  good try and original idea here.', '2005-08-31 20:29:04.000000', NULL, 1),
(1663447, 222674, 20462, '<td valign="top">poor quality and not enough dark to win me over.</td>', 'poor quality and not enough dark to win me over.', '2005-08-31 20:29:20.000000', NULL, 1),
