INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1664219, 223747, 41675, '<td valign="top">Nice composition, but the foreground flower seems overly bright.</td>', 'Nice composition, but the foreground flower seems overly bright.', '2005-08-31 22:31:46.000000', NULL, 1),
(1664225, 223352, 41675, '<td valign="top">I like the setup, but for me, the contrast and saturation are a bit too high. I like the dark background though.</td>', 'I like the setup, but for me, the contrast and saturation are a bit too high. I like the dark background though.', '2005-08-31 22:32:41.000000', NULL, 1),
(1664229, 222752, 41675, '<td valign="top">Hee hee hee. What a fun photo. I like the dark background against the black of the dog''s nose and the model''s black eyelashes and dark hair. Nicely done.</td>', 'Hee hee hee. What a fun photo. I like the dark background against the black of the dog''s nose and the model''s black eyelashes and dark hair. Nicely done.', '2005-08-31 22:33:46.000000', NULL, 1),
(1664233, 223778, 41675, '<td valign="top">Nice angle on the dunes and capturing the pattern as well. I also like the bit of scrub at the top. Good job.</td>', 'Nice angle on the dunes and capturing the pattern as well. I also like the bit of scrub at the top. Good job.', '2005-08-31 22:34:34.000000', NULL, 1),
(1664236, 223956, 41675, '<td valign="top">I think this shot might work better if the boat was off centered to the left and a bit more in focus.</td>', 'I think this shot might work better if the boat was off centered to the left and a bit more in focus.', '2005-08-31 22:35:14.000000', NULL, 1),
(1664240, 222979, 41675, '<td valign="top">Well contrasted photo, but ewww...I''m not a bug fan (but not holding that against you) :)</td>', 'Well contrasted photo, but ewww...I''m not a bug fan (but not holding that against you) :)', '2005-08-31 22:36:08.000000', NULL, 1),
(1664243, 223852, 41675, '<td valign="top">I like the three off centered trees in the foreground. Nice composition as far as city low and lots of sky. Very nice indeed. 8</td>', 'I like the three off centered trees in the foreground. Nice composition as far as city low and lots of sky. Very nice indeed. 8', '2005-08-31 22:37:05.000000', NULL, 1),
(1664247, 221984, 41675, '<td valign="top">:-) My eyes want to look along with the dog and try and see what he (or she) is looking at. Nicely composed, crips, clean and good coloring. 8</td>', ':-) My eyes want to look along with the dog and try and see what he (or she) is looking at. Nicely composed, crips, clean and good coloring. 8', '2005-08-31 22:37:46.000000', NULL, 1),
(1664253, 223370, 41675, '<td valign="top">Great capture. You can just imagine what the driver is thinking as he sees you taking the photo. Good vertical composition and coloring. 9</td>', 'Great capture. You can just imagine what the driver is thinking as he sees you taking the photo. Good vertical composition and coloring. 9', '2005-08-31 22:39:33.000000', NULL, 1),
