(1664289, 223711, 41675, '<td valign="top">A very emotional photo which conveys a story without needing a title. Very moving.</td>', 'A very emotional photo which conveys a story without needing a title. Very moving.', '2005-08-31 22:52:37.000000', NULL, 1),
(1664291, 222123, 41675, '<td valign="top">I''m not a fan of butterflies, but the clarity of your shot is very appealing. Good composition as well. 7</td>', 'I''m not a fan of butterflies, but the clarity of your shot is very appealing. Good composition as well. 7', '2005-08-31 22:53:18.000000', NULL, 1),
(1664293, 223980, 41675, '<td valign="top">Tee hee hee. How very cute. Good background and border choice. Just a cute shot. 8</td>', 'Tee hee hee. How very cute. Good background and border choice. Just a cute shot. 8', '2005-08-31 22:54:23.000000', NULL, 1),
