(1670681, 223412, 25355, '<td valign="top">Marvellous night shot.</td>', 'Marvellous night shot.', '2005-09-03 08:58:49.000000', NULL, 1),
(1670683, 221622, 33392, '<td valign="top">I like this.  I''ve never seen a depressed bird before.</td>', 'I like this.  I''ve never seen a depressed bird before.', '2005-09-03 09:05:08.000000', NULL, 1),
(1670684, 223608, 25355, '<td valign="top">Now, shall I go through the April the First challenge to see if I can recognisse this duckie? Ah, no, won''t bother, but you can have 10 title alone.</td>', 'Now, shall I go through the April the First challenge to see if I can recognisse this duckie? Ah, no, won''t bother, but you can have 10 title alone.', '2005-09-03 09:05:10.000000', NULL, 1),
