(1670759, 222269, 33392, '<td valign="top">Nice in its simplicity.</td>', 'Nice in its simplicity.', '2005-09-03 10:02:29.000000', NULL, 1),
(1670760, 223003, 33392, '<td valign="top">Pretty view.  I would like to see this with more color sometime.</td>', 'Pretty view.  I would like to see this with more color sometime.', '2005-09-03 10:03:01.000000', NULL, 1),
(1670762, 223989, 33392, '<td valign="top">An interesting urban shoot.  Well composed.</td>', 'An interesting urban shoot.  Well composed.', '2005-09-03 10:03:37.000000', NULL, 1),
